   113→    method build_return_node($value_node, $control = undef) {
   114→        # Debug: check what we received
   115→        my $ref_type = ref($value_node) || 'SCALAR';
   116→        my $prefix = substr($ref_type, 0, 15);
   117→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
   118→        unless ($ref_type && $is_node) {
   119→            warn "build_return_node received non-node: $ref_type\n";
   120→            return undef;
   121→        }
   122→
   123→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   124→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   125→
   126→        my $node_id = $self->next_node_id();
   127→        my $return = Chalk::IR::Node::Return->new(
   128→            id            => $node_id,
   129→            inputs        => [$ctrl, $value_node->id],
   130→            value_id      => $value_node->id,
