   189→        return $div;
   190→    }
   191→
   192→    # Generate label with loop depth if inside a loop
   193→    method make_variable_label($var_name) {
   194→        if ($loop_depth > 0) {
   195→            return "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   196→        }
   197→        return "lexical:$var_name";
   198→    }
   199→
   200→    # Create Store node (variable assignment)
   201→    method build_store_node($var_name, $value_node, $control = undef) {
   202→        # Store variable using lexical: namespace in context
   203→        # Inside loops, use loop depth in label: lexical:loop_0:$var
   204→        # Store the IR node object directly, not the node ID
   205→        my $label = $self->make_variable_label($var_name);
   206→        $context = Chalk::IR::Context->extend_context($context, $label, $value_node);
   207→
   208→        # Track this variable as modified if we're in a loop
   209→        if ($loop_depth > 0 && scalar($loop_modified_vars->@*) > 0) {
   210→            my $current_loop_vars = $loop_modified_vars->[-1];
   211→            $current_loop_vars->{$var_name} = 1;
   212→        }
   213→
   214→        return $value_node;
   215→    }
   216→
   217→    # Load node (variable read)
   218→    method build_load_node($var_name) {
   219→        # Retrieve variable using lexical: namespace from context
   220→        # Try loop-scoped label first, then fall back to outer scope
   221→        # Context now stores IR node objects directly, not node IDs
   222→        my $node;
   223→
   224→        # Try current loop depth first (search from innermost to outermost)
   225→        if ($loop_depth > 0) {
   226→            my $depth = $loop_depth - 1;
   227→            while ($depth >= 0) {
   228→                my $label = "lexical:loop_${depth}:$var_name";
   229→                $node = $context->($label);
   230→                last if defined($node);
   231→                $depth--;
   232→            }
   233→        }
   234→
   235→        # Fall back to non-loop lexical scope
   236→        $node //= $context->("lexical:$var_name");
