   495→    # Loop depth tracking methods
   496→    method begin_loop_tracking() {
   497→        # Increment loop depth when entering a loop
   498→        $loop_depth++;
   499→        # Push a new set to track modified variables at this loop depth
   500→        push $loop_modified_vars->@*, {};
   501→        return;
   502→    }
   503→
   504→    method end_loop_tracking() {
   505→        # Decrement loop depth when exiting a loop
   506→        if ($loop_depth > 0) {
   507→            $loop_depth--;
   508→            # Pop the modified variables set for this loop
   509→            pop $loop_modified_vars->@* if scalar($loop_modified_vars->@*) > 0;
   510→        }
   511→        return;
   512→    }
   513→
   514→    method is_tracking_loop() {
   515→        return $loop_depth > 0;
   516→    }
   517→
   518→    method current_loop_depth() {
   519→        return $loop_depth;
   520→    }
   521→
   522→    method generate_loop_phi_nodes($loop_node) {
   523→        # Generate phi nodes for variables modified within the loop
   524→        # With context+labels approach, phi nodes are created for variables
   525→        # that exist both as 'lexical:$var' (pre-loop) and 'lexical:loop_N:$var' (in-loop)
   526→
   527→        my %phi_nodes;
   528→
   529→        # If we're not tracking a loop or have no modified vars, return empty
   530→        return \%phi_nodes unless scalar($loop_modified_vars->@*) > 0;
   531→
   532→        # Get the current loop's modified variables
   533→        my $modified_vars = $loop_modified_vars->[-1];
   534→
   535→        # For each modified variable, create a phi node
   536→        for my $var_name (keys($modified_vars->%*)) {
   537→            # Get pre-loop value (lexical:$var)
   538→            my $pre_loop_label = "lexical:$var_name";
   539→            my $pre_loop_value = $context->($pre_loop_label);
   540→
   541→            # Get loop-modified value (lexical:loop_N:$var where N = current depth - 1)
   542→            my $loop_label = "lexical:loop_" . ($loop_depth - 1) . ":$var_name";
   543→            my $loop_value = $context->($loop_label);
   544→
   545→            # Only create phi if both values exist
   546→            if (defined($pre_loop_value) && defined($loop_value)) {
   547→                # Build phi node with: control (loop), initial value, loop value
   548→                my $phi = $self->build_loop_phi_node(
   549→                    $loop_node,
   550→                    (ref($pre_loop_value) ? $pre_loop_value->id : $pre_loop_value),
   551→                    (ref($loop_value) ? $loop_value->id : $loop_value)
   552→                );
   553→                $phi_nodes{$var_name} = $phi;
   554→            }
   555→        }
   556→
   557→        return \%phi_nodes;
   558→    }
