   922→        my $target_node_or_id = $context->($label);
   923→        die "Cannot create reference to undefined variable $var_name" unless defined($target_node_or_id);
   924→
   925→        # Get the node ID for the dependency
   926→        my $target_node_id = ref($target_node_or_id) ? $target_node_or_id->id : $target_node_or_id;
   927→
   928→        my $node_id = $self->next_node_id();
   929→        my $reference = Chalk::IR::Node::Reference->new(
   930→            id             => $node_id,
   931→            inputs         => [$current_control, $target_node_id],  # Add target as dependency
   932→            target_context => $context,
   933→            target_label   => $label,
   934→        );
   935→        $graph->add_node($reference);
   936→        return $reference;
   937→    }
