   939→    # Create reference to array element: \$arr[1]
   940→    method build_element_ref_node($collection_name, $index_node) {
   941→        # Get the collection from context (might be object or ID)
   942→        my $collection_label = "lexical:$collection_name";
   943→        my $collection_node_or_id = $context->($collection_label);
   944→
   945→        # Get the collection node
   946→        my $collection_node;
   947→        if (ref($collection_node_or_id)) {
   948→            $collection_node = $collection_node_or_id;
   949→        } else {
   950→            $collection_node = $graph->get_node($collection_node_or_id);
   951→        }
   952→
   953→        # Get the array context from the collection node
   954→        my $array_ctx = $collection_node->array_context;
   955→
   956→        # Get the index value - need to evaluate it
   957→        # For now, assume it's a constant node
   958→        my $index_val = $index_node->value;
   959→
   960→        # Create the reference pointing to the array context with index: label
   961→        my $label = Chalk::IR::Context->make_index_label($index_val);
   962→        my $node_id = $self->next_node_id();
   963→        my $reference = Chalk::IR::Node::Reference->new(
   964→            id             => $node_id,
   965→            inputs         => [$current_control, $collection_node->id, $index_node->id],
   966→            target_context => $array_ctx,
   967→            target_label   => $label,
   968→        );
   969→        $graph->add_node($reference);
   970→        return $reference;
   971→    }
