   973→    # Dereference a scalar reference: $$ref
   974→    method build_scalar_deref_node($ref_var_name) {
   975→        # Get the reference from context (might be object or ID)
   976→        my $ref_label = "lexical:$ref_var_name";
   977→        my $ref_node_or_id = $context->($ref_label);
   978→
   979→        # Get the node ID
   980→        my $ref_id = ref($ref_node_or_id) ? $ref_node_or_id->id : $ref_node_or_id;
