        my @inputs = ($loop_node->id, $initial_value);
        push(@inputs, $loop_value) if defined($loop_value);

        my $node_id = $self->next_node_id();
        my $phi = Chalk::IR::Node::Phi->new(
            id            => $node_id,
            inputs        => \@inputs,
            region_id     => $loop_node->id,
        );
        $graph->add_node($phi);
        return $phi;
    }

