            elsif (length($key) >= 3 && substr($key, -3) eq '_id' && defined($value) && exists($redirections->{$value})) {
                $new_attrs{$key} = $redirections->{$value};
            }
            else {
                # Copy as-is for other types
                $new_attrs{$key} = $value;
            }
        }

        return \%new_attrs;
    }
}

