            my $matched_value = substr($input_string, $pos, $match_length);

            # Create a context with the terminal value as focus
            my $terminal_ctx = Chalk::EvalContext->new(
                focus => $matched_value,
                children => [],
                start_pos => $pos,
                end_pos => $pos + $match_length,
                env => $semiring->grammar->start_symbol,  # Use grammar
                grammar => $grammar,
                rule => $item->rule
            );

            my $terminal_element = Chalk::Semiring::SemanticElement->new(
                value => 1,
                context => $terminal_ctx
            );

            # Multiply current element with terminal to accumulate in children
            $scanned_element = $element * $terminal_element;
        } else {
            # All other semirings receive position updates during scan
            # Semirings can choose to use or ignore positions based on their needs
            $scanned_element = $semiring->init_element_from_rule(
                $item->rule,
                $scanned_item->start_pos,
                $scanned_item->end_pos
            );
        }

        $chart->add_element( $scanned_item, $scanned_element );
    }

    # Helper method to convert character position to line and column
    method _pos_to_line_col($input, $pos) {
        my $line = 1;
        my $col = 1;

        for (my $i = 0; $i < $pos && $i < length($input); $i++) {
            if (substr($input, $i, 1) eq "\n") {
                $line++;
                $col = 1;
            } else {
                $col++;
            }
        }

        return ($line, $col);
    }

    # Helper method to extract source context around a position
    method _get_source_context($input, $pos) {
        my ($line_num, $col) = $self->_pos_to_line_col($input, $pos);

        # Split input into lines
        my @lines = split(/\n/, $input, -1);

        # Show 2 lines before, the error line, and 2 lines after
        my $start_line = $line_num - 2 > 0 ? $line_num - 2 : 1;
        my $end_line = $line_num + 2 < scalar(@lines) ? $line_num + 2 : scalar(@lines);

        my $context = "";
        for (my $i = $start_line; $i <= $end_line; $i++) {
            my $line_content = $lines[$i - 1] // "";
            my $marker = ($i == $line_num) ? ">>>" : "   ";
            $context .= sprintf("%s %4d | %s\n", $marker, $i, $line_content);

            # Add a pointer to the exact column on the error line
            if ($i == $line_num) {
                $context .= "         " . (" " x $col) . "^\n";
            }
        }

        return $context;
    }

    # Helper method to get expected symbols at a position
    method _get_expected_symbols($chart, $pos) {
        my @items = $chart->items_ending_at($pos);
        my %expected;

        for my $item (@items) {
            next if $item->complete;
            my $next_sym = $item->next_symbol;
            if (defined($next_sym)) {
                # Format the symbol nicely
                my $sym_str;
                if (ref($next_sym) eq 'Regexp') {
                    $sym_str = "regex: $next_sym";
                } else {
                    $sym_str = $next_sym;
                }
                $expected{$sym_str} = 1;
            }
        }

        return sort keys %expected;
    }

    # Helper method to get active rules at a position
    method _get_active_rules($chart, $pos) {
        my @items = $chart->items_ending_at($pos);
        my @rules;
        my %seen;

        for my $item (@items) {
            next if $item->complete;
            my $rule = $item->rule;
            my $rule_str = $rule->lhs . " →";

            # Show the rule with a dot indicating position
            my @rhs = $rule->rhs->@*;
            for (my $i = 0; $i < scalar(@rhs); $i++) {
                if ($i == $item->dot_pos) {
                    $rule_str .= " •";
                }
                my $sym = $rhs[$i];
                if (ref($sym) eq 'Regexp') {
                    $rule_str .= " /$sym/";
                } else {
                    $rule_str .= " $sym";
                }
            }
            if ($item->dot_pos == scalar(@rhs)) {
                $rule_str .= " •";
            }

            # Only add unique rules
            unless ($seen{$rule_str}) {
                push(@rules, $rule_str);
                $seen{$rule_str} = 1;
            }
        }

        return @rules;
    }
}

